/*
 * Generates the SOURCE images that @capacitor/assets consumes to produce
 * the NATIVE Android launcher icons (and iOS icons).
 *
 * These are different from the web/PWA icons in ./icons — those are only used
 * by manifest.json in the browser/PWA layer and are NOT the launcher icon that
 * shows on your phone's home screen. The launcher icon is generated by
 * @capacitor/assets from the files this script writes into ./assets.
 *
 * Run:  npm run assets:source   (regenerate these source images)
 * Then: npm run assets          (generate native icons into android/)
 */
const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

const assetsDir = path.join(__dirname, 'assets');
if (!fs.existsSync(assetsDir)) fs.mkdirSync(assetsDir, { recursive: true });

// Brand gradient background (indigo -> purple -> pink), full-bleed 1024x1024.
const backgroundSvg = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024">
  <defs>
    <linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#6366f1"/>
      <stop offset="50%" stop-color="#8b5cf6"/>
      <stop offset="100%" stop-color="#ec4899"/>
    </linearGradient>
  </defs>
  <rect width="1024" height="1024" fill="url(#bg)"/>
</svg>`;

// Adaptive-icon FOREGROUND: transparent canvas with the dark rounded panel,
// the summation glyph, and the accent dots kept inside the central safe zone
// (launchers may crop the outer ~1/3 of an adaptive icon).
const foregroundSvg = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024">
  <defs>
    <linearGradient id="inner" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0a0e1a"/>
      <stop offset="100%" stop-color="#1a1f38"/>
    </linearGradient>
  </defs>
  <rect x="182" y="182" width="660" height="660" rx="119" fill="url(#inner)"/>
  <text x="512" y="650" text-anchor="middle" fill="white"
        font-family="'JetBrains Mono', monospace" font-size="396" font-weight="700">&#8721;</text>
  <circle cx="321" cy="321" r="20" fill="#6366f1" opacity="0.85"/>
  <circle cx="703" cy="321" r="20" fill="#ec4899" opacity="0.85"/>
  <circle cx="321" cy="703" r="20" fill="#8b5cf6" opacity="0.85"/>
  <circle cx="703" cy="703" r="20" fill="#06b6d4" opacity="0.85"/>
</svg>`;

// Legacy (non-adaptive) icon: the complete branded mark, edge to edge.
const iconOnlySvg = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024">
  <defs>
    <linearGradient id="bg2" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#6366f1"/>
      <stop offset="50%" stop-color="#8b5cf6"/>
      <stop offset="100%" stop-color="#ec4899"/>
    </linearGradient>
    <linearGradient id="inner2" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0a0e1a"/>
      <stop offset="100%" stop-color="#1a1f38"/>
    </linearGradient>
  </defs>
  <rect width="1024" height="1024" rx="224" fill="url(#bg2)"/>
  <rect x="112" y="112" width="800" height="800" rx="144" fill="url(#inner2)"/>
  <text x="512" y="680" text-anchor="middle" fill="white"
        font-family="'JetBrains Mono', monospace" font-size="480" font-weight="700">&#8721;</text>
  <circle cx="280" cy="280" r="24" fill="#6366f1" opacity="0.85"/>
  <circle cx="744" cy="280" r="24" fill="#ec4899" opacity="0.85"/>
  <circle cx="280" cy="744" r="24" fill="#8b5cf6" opacity="0.85"/>
  <circle cx="744" cy="744" r="24" fill="#06b6d4" opacity="0.85"/>
</svg>`;

// Splash: centered mark on the app's dark background color.
const splashSvg = (bg) => `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 2732 2732">
  <defs>
    <linearGradient id="bg3" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#6366f1"/>
      <stop offset="50%" stop-color="#8b5cf6"/>
      <stop offset="100%" stop-color="#ec4899"/>
    </linearGradient>
    <linearGradient id="inner3" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0a0e1a"/>
      <stop offset="100%" stop-color="#1a1f38"/>
    </linearGradient>
  </defs>
  <rect width="2732" height="2732" fill="${bg}"/>
  <rect x="1116" y="1116" width="500" height="500" rx="112" fill="url(#bg3)"/>
  <rect x="1155" y="1155" width="422" height="422" rx="76" fill="url(#inner3)"/>
  <text x="1366" y="1490" text-anchor="middle" fill="white"
        font-family="'JetBrains Mono', monospace" font-size="252" font-weight="700">&#8721;</text>
</svg>`;

(async () => {
  const jobs = [
    ['icon-background.png', backgroundSvg],
    ['icon-foreground.png', foregroundSvg],
    ['icon-only.png', iconOnlySvg],
    ['splash.png', splashSvg('#0a0e1a')],
    ['splash-dark.png', splashSvg('#0a0e1a')],
  ];
  console.log('Generating @capacitor/assets source images into ./assets ...');
  for (const [name, svg] of jobs) {
    await sharp(Buffer.from(svg)).png().toFile(path.join(assetsDir, name));
    console.log(`  ✓ assets/${name}`);
  }
  console.log('\nDone. Next: npm run assets  (writes native launcher icons into android/).');
})().catch((e) => { console.error(e); process.exit(1); });
